"use client";
import { useCallback, useMemo, useState } from "react";
import { curveLinear, curveStepAfter } from "@visx/curve";
import { Area, AreaChart } from "@ui/area-chart";
import { Grid, XAxis, YAxis, ChartTooltip, TooltipContent, } from "@ui/chart-core";
import { ChartDataTable, chartColor } from "@ui/chart-primitives";
import { cn } from "@lib/utils";
import { agentRunsChartData, runCost, runDuration, type AgentRunsFormatters, } from "./agent-runs-data";
import type { AgentRun, AgentRunsData, AgentRunsLabels, AgentRunsMode, } from "./agent-runs-types";
export function AgentRunsChart({ data, mode, labels, format, selectedId, onSelect, }: {
    data: AgentRunsData;
    mode: AgentRunsMode;
    labels: AgentRunsLabels;
    format: AgentRunsFormatters;
    selectedId?: string;
    onSelect: (id: string) => void;
}) {
    const points = useMemo(() => agentRunsChartData(data, mode), [data, mode]);
    const [focusedIds, setFocusedIds] = useState<Record<string, string>>({});
    const lanes = useMemo(() => {
        const byAgent = new Map<string, AgentRun[]>();
        for (const run of data.runs) {
            const lane = byAgent.get(run.agentId);
            if (lane)
                lane.push(run);
            else
                byAgent.set(run.agentId, [run]);
        }
        return data.agents.map((agent) => ({
            agent,
            runs: (byAgent.get(agent.id) ?? []).sort((a, b) => a.startedAt - b.startedAt || a.id.localeCompare(b.id)),
        }));
    }, [data.agents, data.runs]);
    const domain = useMemo<[
        Date,
        Date
    ]>(() => [new Date(data.start), new Date(data.end)], [data.start, data.end]);
    const formatTick = useCallback((date: Date) => {
        const span = data.end - data.start;
        if (span < 60000)
            return format.timeWithSeconds(date.getTime());
        if (span < 86400000)
            return format.time(date.getTime());
        return format.date(date);
    }, [data.start, data.end, format]);
    const title = mode === "cumulative" ? labels.cumulative : labels.perRun;
    const rows = useMemo(() => points.map((point, index) => ({
        id: String(index),
        label: `${format.fullDate(point.date)} ${format.time(point.date)}`,
        values: [format.money(point.value)],
    })), [points, format]);
    const accessibleData = useMemo(() => rows.map((row) => ({ [labels.time]: row.label, [title]: row.values[0] })), [rows, labels.time, title]);
    return (<div className="min-w-0" data-slot="agent-runs-chart" data-mode={mode}>
      <div className="min-w-0" role="group" aria-label={`${labels.chartTitle} · ${title}`}>
        {points.length ? (<AreaChart data={points} accessibleData={accessibleData} xDomain={domain} xDomainSlotCount={0} margin={{ top: 20, bottom: 30, left: 92, right: 64 }} style={{ height: 240, aspectRatio: "auto" }} yDomain={[0, "dataMax"]} animationDuration={0} yDomainTween={false}>
            <Grid horizontal/>
            <Area dataKey="value" stroke={chartColor(1)} fill={chartColor(1)} curve={mode === "cumulative" ? curveStepAfter : curveLinear} fillOpacity={0.25} gradientToOpacity={0} showMarkers={mode === "per-run"} markers={{ radius: 2, strokeWidth: 0, ringGap: 0 }} animate={false}/>
            <XAxis tickMode="domain" numTicks={3} formatDate={formatTick}/>
            <YAxis orientation="right" numTicks={4} formatValue={format.axisMoney}/>
            <ChartTooltip showDatePill={false} content={({ point }) => (<TooltipContent title={`${format.fullDate(Number(point.date))} · ${format.time(Number(point.date))}`} rows={[
                    {
                        label: title,
                        value: format.money(Number(point.value)),
                        color: chartColor(1),
                    },
                ]}/>)}/>
          </AreaChart>) : (<p className="flex h-60 items-center justify-center text-body text-fg-muted">
            {labels.unreported}
          </p>)}
      </div>
      <div className="mt-1 space-y-2" role="group" aria-label={labels.activity}>
        {lanes.map(({ agent, runs }) => {
            const tabId = runs.find((item) => item.id === focusedIds[agent.id])?.id ??
                runs.find((item) => item.id === selectedId)?.id ??
                runs[0]?.id;
            return (<div key={agent.id} className="grid min-w-0 grid-cols-[5rem_minmax(0,1fr)] items-center gap-3 pr-16">
              <span className="flex min-w-0 items-center gap-2 text-label text-fg-muted">
                <span aria-hidden="true" className="size-2 shrink-0 rounded-full" style={{ backgroundColor: chartColor(agent.colorIndex) }}/>
                <span className="truncate" title={agent.name}>
                  {agent.name}
                </span>
              </span>
              <div className="relative h-6 min-w-0 rounded-md bg-surface-raised">
                {runs.map((run, index) => {
                    const left = ((run.startedAt - data.start) / (data.end - data.start)) *
                        100;
                    const width = (runDuration(run, data.end) / (data.end - data.start)) *
                        100;
                    const cost = runCost(run);
                    const description = `${agent.name} · ${run.trigger} · ${format.time(run.startedAt)} · ${format.duration(runDuration(run, data.end))} · ${labels[run.status]} · ${cost === null ? labels.unreported : format.money(cost)}`;
                    return (<button key={run.id} type="button" title={description} aria-label={labels.expand(description)} aria-pressed={selectedId === run.id} onClick={() => onSelect(run.id)} tabIndex={run.id === tabId ? 0 : -1} onFocus={() => setFocusedIds((current) => ({
                            ...current,
                            [agent.id]: run.id,
                        }))} onKeyDown={(event) => {
                            const next = event.key === "ArrowRight"
                                ? Math.min(index + 1, runs.length - 1)
                                : event.key === "ArrowLeft"
                                    ? Math.max(index - 1, 0)
                                    : event.key === "Home"
                                        ? 0
                                        : event.key === "End"
                                            ? runs.length - 1
                                            : undefined;
                            if (next === undefined)
                                return;
                            event.preventDefault();
                            event.currentTarget.parentElement
                                ?.querySelectorAll<HTMLButtonElement>("button")[next]?.focus();
                        }} className={cn("absolute inset-y-1 min-w-1 rounded-sm opacity-75 transition-opacity duration-fast hover:opacity-100 focus-visible:z-control focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring", selectedId === run.id &&
                            "z-content opacity-100 ring-2 ring-focus-ring ring-offset-2 ring-offset-surface-floating", run.status === "cancelled" && "opacity-40")} style={{
                            left: `${Math.min(left, 99.5)}%`,
                            width: `${Math.min(width, 100 - left)}%`,
                            backgroundColor: chartColor(agent.colorIndex),
                        }}/>);
                })}
              </div>
            </div>);
        })}
      </div>
      <ChartDataTable caption={`${labels.chartTitle} · ${title}`} summary={labels.viewData} columns={[labels.time, title]} rows={rows}/>
    </div>);
}

import type { AgentRun, AgentRunsData, AgentRunsLabels, AgentRunsMode, } from "./agent-runs-types";
export const usageKinds = [
    "input",
    "output",
    "cacheRead",
    "cacheWrite",
] as const;
const nonnegative = (value: number) => Number.isFinite(value) && value >= 0;
const unique = (items: readonly {
    id: string;
}[]) => items.every((item) => item.id.trim()) &&
    new Set(items.map((item) => item.id)).size === items.length;
export const runCost = (run: AgentRun) => run.usage === null
    ? null
    : usageKinds.reduce((sum, kind) => sum + run.usage![kind].cost, 0);
export const runTokens = (run: AgentRun) => run.usage === null
    ? null
    : usageKinds.reduce((sum, kind) => sum + run.usage![kind].tokens, 0);
export const runDuration = (run: AgentRun, end: number) => (run.endedAt ?? end) - run.startedAt;
export function cacheRatio(run: AgentRun) {
    if (!run.usage)
        return null;
    const input = run.usage.input.tokens + run.usage.cacheRead.tokens;
    return input > 0 ? run.usage.cacheRead.tokens / input : null;
}
export function validateAgentRunsData(data: AgentRunsData) {
    if (!data.id.trim() ||
        !data.project.name.trim() ||
        !/^[A-Z]{3}$/.test(data.currency) ||
        !Number.isFinite(new Date(data.start).getTime()) ||
        !Number.isFinite(new Date(data.end).getTime()) ||
        data.end <= data.start ||
        !unique(data.agents) ||
        !unique(data.models) ||
        !unique(data.runs) ||
        [...data.agents, ...data.models].some((item) => !Number.isInteger(item.colorIndex) ||
            item.colorIndex < 1 ||
            item.colorIndex > 5))
        return false;
    const agents = new Set(data.agents.map((agent) => agent.id));
    const models = new Set(data.models.map((model) => model.id));
    for (const run of data.runs) {
        if (!agents.has(run.agentId) ||
            (run.modelId !== undefined && !models.has(run.modelId)) ||
            !["running", "completed", "cancelled", "failed"].includes(run.status) ||
            !Number.isFinite(run.startedAt) ||
            run.startedAt < data.start ||
            run.startedAt > data.end ||
            (run.status === "running"
                ? run.endedAt !== null
                : run.endedAt === null) ||
            (run.endedAt !== null &&
                (!Number.isFinite(run.endedAt) ||
                    run.endedAt < run.startedAt ||
                    run.endedAt > data.end)) ||
            (run.cacheSavings !== undefined && !nonnegative(run.cacheSavings)))
            return false;
        if (run.usage !== null &&
            (!run.modelId ||
                usageKinds.some((kind) => !run.usage?.[kind] ||
                    !Number.isSafeInteger(run.usage[kind].tokens) ||
                    run.usage[kind].tokens < 0 ||
                    !nonnegative(run.usage[kind].cost))))
            return false;
    }
    const summary = summarizeAgentRuns(data.runs, data.end);
    return (Number.isFinite(summary.cost) &&
        Number.isSafeInteger(summary.tokens) &&
        Number.isFinite(summary.duration));
}
export function summarizeAgentRuns(runs: readonly AgentRun[], end: number) {
    const agentCosts = new Map<string, number>();
    const modelCosts = new Map<string, number>();
    let cost = 0, tokens = 0, output = 0, cacheRead = 0, input = 0, duration = 0, active = 0, cancelled = 0, unreported = 0;
    for (const run of runs) {
        duration += runDuration(run, end);
        if (run.status === "running")
            active += 1;
        if (run.status === "cancelled")
            cancelled += 1;
        if (!run.usage) {
            unreported += 1;
            continue;
        }
        const reportedCost = runCost(run)!;
        cost += reportedCost;
        tokens += runTokens(run)!;
        agentCosts.set(run.agentId, (agentCosts.get(run.agentId) ?? 0) + reportedCost);
        if (run.modelId !== undefined)
            modelCosts.set(run.modelId, (modelCosts.get(run.modelId) ?? 0) + reportedCost);
        output += run.usage.output.tokens;
        cacheRead += run.usage.cacheRead.tokens;
        input += run.usage.input.tokens;
    }
    return {
        cost,
        tokens,
        output,
        duration,
        active,
        cancelled,
        unreported,
        agentCosts,
        modelCosts,
        cacheRatio: input + cacheRead > 0 ? cacheRead / (input + cacheRead) : null,
    };
}
/** A cumulative step is recorded at completion, or the reporting-window end for active usage. */
export function agentRunsChartData(data: AgentRunsData, mode: AgentRunsMode) {
    const events = data.runs
        .filter((run) => run.usage !== null)
        .map((run) => ({ date: run.endedAt ?? data.end, cost: runCost(run)! }))
        .sort((a, b) => a.date - b.date);
    if (!events.length)
        return [];
    if (mode === "per-run")
        return events.map((event) => ({ date: event.date, value: event.cost }));
    const points = [{ date: data.start, value: 0 }];
    let cost = 0;
    for (const event of events) {
        cost += event.cost;
        if (points[points.length - 1].date === event.date)
            points[points.length - 1].value = cost;
        else
            points.push({ date: event.date, value: cost });
    }
    if (points[points.length - 1].date !== data.end)
        points.push({ date: data.end, value: cost });
    return points;
}
export function createAgentRunsFormatters(locale: string, timeZone: string, currency: string, labels: AgentRunsLabels) {
    let resolvedLocale = locale, resolvedZone = timeZone;
    try {
        new Intl.NumberFormat(locale);
    }
    catch {
        resolvedLocale = "en-US";
    }
    try {
        new Intl.DateTimeFormat(resolvedLocale, { timeZone }).format(0);
    }
    catch {
        resolvedZone = "UTC";
    }
    const number = new Intl.NumberFormat(resolvedLocale);
    const compact = new Intl.NumberFormat(resolvedLocale, {
        notation: "compact",
        maximumFractionDigits: 1,
    });
    const money = new Intl.NumberFormat(resolvedLocale, {
        style: "currency",
        currency: /^[A-Z]{3}$/.test(currency) ? currency : "USD",
    });
    const minorUnit = 10 ** -(money.resolvedOptions().maximumFractionDigits ?? 2);
    const preciseMoney = new Intl.NumberFormat(resolvedLocale, {
        style: "currency",
        currency: money.resolvedOptions().currency,
        maximumSignificantDigits: 4,
    });
    const percent = new Intl.NumberFormat(resolvedLocale, {
        style: "percent",
        maximumFractionDigits: 0,
    });
    const date = new Intl.DateTimeFormat(resolvedLocale, {
        timeZone: resolvedZone,
        month: "short",
        day: "numeric",
    });
    const fullDate = new Intl.DateTimeFormat(resolvedLocale, {
        timeZone: resolvedZone,
        year: "numeric",
        month: "short",
        day: "numeric",
    });
    const time = new Intl.DateTimeFormat(resolvedLocale, {
        timeZone: resolvedZone,
        hour: "2-digit",
        minute: "2-digit",
        hourCycle: "h23",
    });
    const timeWithSeconds = new Intl.DateTimeFormat(resolvedLocale, {
        timeZone: resolvedZone,
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        hourCycle: "h23",
    });
    const day = new Intl.DateTimeFormat("en-CA", {
        timeZone: resolvedZone,
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
    });
    return {
        number: number.format,
        compact: compact.format,
        money: (value: number) => value !== 0 && Math.abs(value) < minorUnit
            ? preciseMoney.format(value)
            : money.format(value),
        axisMoney: preciseMoney.format,
        percent: percent.format,
        date: (value: number | Date) => date.format(value),
        fullDate: (value: number) => fullDate.format(value),
        time: (value: number) => time.format(value),
        timeWithSeconds: (value: number) => timeWithSeconds.format(value),
        day: (value: number) => day.format(value),
        duration: (ms: number) => ms < 60000
            ? labels.underMinute
            : labels.duration(number.format(Math.floor(ms / 3600000)), number.format(Math.floor(ms / 60000) % 60)),
    };
}
export type AgentRunsFormatters = ReturnType<typeof createAgentRunsFormatters>;

import type { AgentRun, AgentRunsData } from "./agent-runs-types";
/** Deterministic illustrative records; not live model pricing or usage. */
export function createAgentRunsDemoData(zh = false): AgentRunsData {
    const start = Date.parse("2026-10-28T14:00:00+08:00");
    const end = Date.parse("2026-10-31T04:00:00+08:00");
    const prompts = zh
        ? [
            "梳理项目结构与组件依赖",
            "实现项目概览与导航",
            "补充边界状态和交互反馈",
            "对齐图表的主题与坐标轴",
            "检查响应式布局和键盘操作",
            "再看一下费用明细",
            "按照这个设计来改，保留现有组件",
        ]
        : [
            "Map the project structure and component dependencies",
            "Build the project overview and navigation",
            "Add edge states and interaction feedback",
            "Align chart theme and axes",
            "Check responsive layout and keyboard access",
            "Take another look at the cost breakdown",
            "Apply this design using our existing components",
        ];
    const runs: AgentRun[] = [];
    // Cost buckets conserve the reference's agent and model distributions.
    for (let i = 0; i < 88; i += 1) {
        const emacs = i >= 86;
        const modelId = emacs ? "sol" : i >= 72 ? "opus-xhigh" : "opus-high";
        const cents = emacs
            ? 142
            : i >= 72
                ? i === 85
                    ? 578
                    : i === 84
                        ? 169
                        : 173
                : i === 71
                    ? 219
                    : 211;
        const offset = i < 56
            ? (i / 55) * 13.5
            : i < 72
                ? 24 + ((i - 56) / 15) * 4
                : i < 78
                    ? 49 + ((i - 72) / 5) * 1.2
                    : 55.7 + ((i - 78) / 9) * 1.9;
        const duration = (7 + ((i * 7) % 24)) * 60000;
        const startedAt = start + offset * 3600000;
        const cost = cents / 100;
        const inputCost = Math.round(cost * 0.01 * 100) / 100;
        const outputCost = Math.round(cost * 0.35 * 100) / 100;
        const cacheCost = Math.round(cost * 0.43 * 100) / 100;
        const cached = 3000000 + ((i * 7919) % 3000000);
        runs.push({
            id: `run-${i + 1}`,
            trigger: prompts[i % prompts.length],
            agentId: emacs ? "emacs" : "lambda",
            modelId,
            status: [19, 48, 76].includes(i) ? "cancelled" : "completed",
            startedAt,
            endedAt: startedAt + duration,
            usage: {
                input: { tokens: Math.round(cached / 49), cost: inputCost },
                output: { tokens: 18000 + i * 317, cost: outputCost },
                cacheRead: { tokens: cached, cost: cacheCost },
                cacheWrite: {
                    tokens: 80000 + i * 827,
                    cost: Math.round((cost - inputCost - outputCost - cacheCost) * 100) / 100,
                },
            },
            cacheSavings: Math.round(cost * 8.2 * 100) / 100,
        });
    }
    // Pin the most recent completed session to the expanded reference record.
    runs[85] = {
        ...runs[85],
        trigger: zh
            ? "再看一下这个项目的运行记录"
            : "Review the project’s run history",
        startedAt: end - 27 * 60000,
        endedAt: end - 4 * 60000,
        usage: {
            input: { tokens: 152, cost: 0 },
            output: { tokens: 102700, cost: 2.05 },
            cacheRead: { tokens: 12500000, cost: 2.49 },
            cacheWrite: { tokens: 247200, cost: 1.24 },
        },
        cacheSavings: 47.39,
    };
    runs.push({
        id: "run-active",
        trigger: zh
            ? "按照这个设计来改，保留现有组件"
            : "Apply this design using our existing components",
        agentId: "lambda",
        status: "running",
        startedAt: end - 5 * 60000,
        endedAt: null,
        usage: null,
    });
    return {
        id: "zeron-project-runs",
        project: { name: "Zeron UI · Component library", identifier: "ZER-8317" },
        currency: "USD",
        start,
        end,
        agents: [
            { id: "lambda", name: "Lambda", colorIndex: 1 },
            { id: "emacs", name: "Emacs", colorIndex: 2 },
        ],
        models: [
            { id: "opus-high", name: "Opus 5.5 high", colorIndex: 1 },
            { id: "opus-xhigh", name: "Opus 5.5 xhigh", colorIndex: 2 },
            { id: "sol", name: "GPT-6.1 Sol", colorIndex: 5 },
        ],
        runs,
    };
}

"use client";
import { useId, useMemo } from "react";
import type { ColumnDef, OnChangeFn, PaginationState, } from "@tanstack/react-table";
