}
const statusTone = {
    running: "info",
    completed: "success",
    cancelled: "neutral",
    failed: "danger",
} as const;
export function AgentRunState({ status, labels, }: {
    status: AgentRunStatus;
    labels: AgentRunsLabels;
}) {
